import time

class Thermostat:
    VALID_MODES = ('heat', 'cool')
    TEMPERATURE_STEP = 1

    def __init__(self, current_temperature, target_temperature, mode):
        self._current_temperature = current_temperature
        self._target_temperature = target_temperature
        self._mode = mode

    def get_target_temperature(self):
        return self._target_temperature

    def set_target_temperature(self, temperature):
        self._target_temperature = temperature

    def get_mode(self):
        return self._mode

    def set_mode(self, mode):
        if mode in self.VALID_MODES:
            self._mode = mode
            return True
        else:
            return False

    def auto_set_mode(self):
        if self.current_temperature < self.target_temperature:
            self._mode = 'heat'
        else:
            self._mode = 'cool'

    def current_temperature(self):
        return self._current_temperature

    def target_temperature(self):
        return self._target_temperature

    def auto_check_conflict(self):
        if self._current_temperature > self._target_temperature:
            return self._mode == 'cool' or self._handle_conflict('cool')
        else:
            return self._mode == 'heat' or self._handle_conflict('heat')

    def _handle_conflict(self, expected_mode):
        if self._mode != expected_mode:
            self.auto_set_mode()
        return False

    def simulate_operation(self):
        self.auto_set_mode()
        use_time = 0
        if self._mode == 'heat':
            while self._current_temperature < self._target_temperature:
                self._current_temperature += self.TEMPERATURE_STEP
                use_time += 1
        else:
            while self._current_temperature > self._target_temperature:
                self._current_temperature -= self.TEMPERATURE_STEP
                use_time += 1
        return use_time
